const MILLISECONDS_PER_DAY = 86400000;
const FIRST_DAY = parseDate("0000-01-01");
const LAST_DAY = parseDate("9999-12-31");

function parseDate(value) {
  if (
    typeof value !== "string" ||
    value.length !== 10 ||
    !/^\d{4}-\d{2}-\d{2}$/.test(value)
  ) {
    throw new RangeError("Expected a real calendar date in YYYY-MM-DD form.");
  }

  const year = Number(value.slice(0, 4));
  const month = Number(value.slice(5, 7));
  const day = Number(value.slice(8, 10));

  // UTC avoids timezone effects; setUTCFullYear also handles years 0000–0099.
  const date = new Date(0);
  date.setUTCFullYear(year, month - 1, day);

  if (
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() !== month - 1 ||
    date.getUTCDate() !== day
  ) {
    throw new RangeError("Expected a real calendar date in YYYY-MM-DD form.");
  }

  return date.getTime() / MILLISECONDS_PER_DAY;
}

function weekday(day) {
  // Unix day zero was a Thursday. Normalize negative remainders.
  return ((day + 4) % 7 + 7) % 7;
}

function isWeekday(day) {
  const dayOfWeek = weekday(day);
  return dayOfWeek >= 1 && dayOfWeek <= 5;
}

function observedHolidayDays(holidays) {
  if (!Array.isArray(holidays)) {
    throw new RangeError("holidays must be an array of calendar dates.");
  }

  const observed = new Set();
  const weekends = [];

  // Reserve every weekday holiday before placing any weekend holiday.
  for (const holiday of holidays) {
    const day = parseDate(holiday);
    if (isWeekday(day)) {
      observed.add(day);
    } else {
      weekends.push(day);
    }
  }

  weekends.sort((a, b) => a - b);

  let afterPrevious = -Infinity;
  for (const day of weekends) {
    const nextMonday = day + (weekday(day) === 6 ? 2 : 1);

    // Sorted weekend holidays have nondecreasing observation dates.
    let candidate = Math.max(nextMonday, afterPrevious);
    while (!isWeekday(candidate) || observed.has(candidate)) {
      candidate += 1;
    }

    observed.add(candidate);
    afterPrevious = candidate + 1;
  }

  return Array.from(observed).sort((a, b) => a - b);
}

function upperBound(sortedDays, day) {
  let low = 0;
  let high = sortedDays.length;

  while (low < high) {
    const middle = low + Math.floor((high - low) / 2);
    if (sortedDays[middle] <= day) {
      low = middle + 1;
    } else {
      high = middle;
    }
  }

  return low;
}

// Counts business days in (start, end], where start <= end.
function countForward(start, end, observed) {
  const length = end - start;
  const fullWeeks = Math.floor(length / 7);
  const remainder = length % 7;
  let count = fullWeeks * 5;

  for (let offset = 1; offset <= remainder; offset += 1) {
    if (isWeekday(start + offset)) {
      count += 1;
    }
  }

  return count - (upperBound(observed, end) - upperBound(observed, start));
}

function formatDate(day) {
  return new Date(day * MILLISECONDS_PER_DAY).toISOString().slice(0, 10);
}

export function isBusinessDay(date, holidays = []) {
  const day = parseDate(date);
  const observed = observedHolidayDays(holidays);
  const index = upperBound(observed, day);

  return (
    isWeekday(day) &&
    (index === 0 || observed[index - 1] !== day)
  );
}

export function addBusinessDays(date, n, holidays = []) {
  const day = parseDate(date);

  if (!Number.isInteger(n)) {
    throw new RangeError("n must be an integer.");
  }

  const observed = observedHolidayDays(holidays);
  const origin = FIRST_DAY - 1;

  // Use a one-based business-day ordinal rather than walking n days.
  // For zero, select the first business day at or after the start.
  const ordinal =
    n > 0
      ? countForward(origin, day, observed) + n
      : countForward(origin, day - 1, observed) + n + 1;

  const total = countForward(origin, LAST_DAY, observed);
  if (ordinal < 1 || ordinal > total) {
    throw new RangeError("Result is outside the YYYY-MM-DD date range.");
  }

  let low = FIRST_DAY;
  let high = LAST_DAY;

  while (low < high) {
    const middle = low + Math.floor((high - low) / 2);
    if (countForward(origin, middle, observed) < ordinal) {
      low = middle + 1;
    } else {
      high = middle;
    }
  }

  return formatDate(low);
}

export function businessDaysBetween(start, end, holidays = []) {
  const startDay = parseDate(start);
  const endDay = parseDate(end);
  const observed = observedHolidayDays(holidays);

  if (startDay === endDay) {
    return 0;
  }

  if (startDay < endDay) {
    return countForward(startDay, endDay, observed);
  }

  const count = countForward(endDay, startDay, observed);
  return count === 0 ? 0 : -count;
}
